function Order() {
  const [activeCategory, setActiveCategory] = useState(categories[0]);
  const [cart, setCart] = useState({});

  // Read the selected category directly from the menu data.
  const groups = menuItems[activeCategory] ?? [];
  const items = groups.flatMap((group) => group.items ?? []);

  // Calculate the cart total across every category, not only the visible one.
  const allMenuItems = Object.values(menuItems).flatMap((categoryGroups) =>
    categoryGroups.flatMap((group) => group.items ?? [])
  );
  const cartCount = Object.values(cart).reduce((sum, quantity) => sum + quantity, 0);
  const cartTotal = Object.entries(cart).reduce((sum, [name, quantity]) => {
    const item = allMenuItems.find((entry) => entry.name === name);
    return sum + (item ? item.price * quantity : 0);
  }, 0);

  const addItem = (name) => {
    setCart((current) => ({ ...current, [name]: (current[name] || 0) + 1 }));
  };

  const removeItem = (name) => {
    setCart((current) => {
      const next = { ...current };
      if (!next[name] || next[name] <= 1) delete next[name];
      else next[name] -= 1;
      return next;
    });
  };

  return (
    <div className="order-online-page">
      <div className="order-heading-row">
        <div>
          <p className="order-eyebrow">GRAND PAVILION</p>
          <h2 className="order-title">Order Online</h2>
        </div>
        <div className="order-summary">
          <span className="order-cart-count">Your order · {cartCount} items</span>
          {cartCount > 0 && <span className="order-cart-total">₹{cartTotal}</span>}
        </div>
      </div>

      <div className="order-layout">
        <aside className="order-sidebar" aria-label="Menu categories">
          <p className="order-sidebar-title">MENU CATEGORIES</p>
          {categories.map((category) => {
            const categoryCount = (menuItems[category] ?? []).reduce(
              (sum, group) => sum + (group.items?.length ?? 0),
              0
            );

            return (
              <button
                key={category}
                type="button"
                className={`order-category${activeCategory === category ? " active" : ""}`}
                onClick={() => setActiveCategory(category)}
                aria-pressed={activeCategory === category}
              >
                <span className="order-category-name">{category}</span>
                <span className="order-category-count">{categoryCount}</span>
              </button>
            );
          })}
        </aside>

        <section className="order-menu" aria-live="polite">
          <div className="order-menu-heading">
            <div>
              <h2>{activeCategory}</h2>
              <p>{items.length} {items.length === 1 ? "dish" : "dishes"}</p>
            </div>
          </div>

          <div className="order-food-list">
            {items.length === 0 ? (
              <div className="order-empty-state">
                <h3>No dishes available</h3>
                <p>Please select another menu category.</p>
              </div>
            ) : (
              groups.map((group, groupIndex) => (
                <div
                  className="order-food-group"
                  key={`${activeCategory}-${group.section || groupIndex}`}
                >
                  {group.section && (
                    <h3 className="order-food-section-title">{group.section}</h3>
                  )}

                  {(group.items ?? []).map((item) => (
                    <article className="order-food-item" key={item.name}>
                      <div className="order-food-image-wrap">
                        <img
                          className="order-food-image"
                          src={item.image}
                          alt={item.name}
                          loading="lazy"
                          onError={(event) => {
                            event.currentTarget.classList.add("image-not-found");
                          }}
                        />
                      </div>

                      <div className="order-food-details">
                        <div className="order-food-name-row">
                          <h4>{item.name}</h4>
                          {item.vegetarian && (
                            <span className="order-veg-indicator" aria-label="Vegetarian" />
                          )}
                        </div>
                        <p className="order-food-price">₹{item.price}</p>
                        {item.description && (
                          <p className="order-food-description">{item.description}</p>
                        )}
                        {item.customizable && (
                          <span className="order-customizable">customizable</span>
                        )}
                      </div>

                      <div className="order-add-control">
                        {cart[item.name] ? (
                          <div className="order-quantity-control">
                            <button
                              type="button"
                              onClick={() => removeItem(item.name)}
                              aria-label={`Remove one ${item.name}`}
                            >
                              −
                            </button>
                            <span>{cart[item.name]}</span>
                            <button
                              type="button"
                              onClick={() => addItem(item.name)}
                              aria-label={`Add one ${item.name}`}
                            >
                              +
                            </button>
                          </div>
                        ) : (
                          <button
                            className="order-add-button"
                            type="button"
                            onClick={() => addItem(item.name)}
                          >
                            ADD&nbsp; +
                          </button>
                        )}
                      </div>
                    </article>
                  ))}
                </div>
              ))
            )}
          </div>
        </section>
      </div>
    </div>
  );
}

export default Order;
